import { useEffect, useRef, useState, useCallback } from "react";
import { useGetChatMessages, useSendChatMessage } from "@workspace/api-client-react";
import type { ChatMessage } from "@workspace/api-client-react";
import { useAuth } from "@/lib/auth";
import { useToast } from "@/hooks/use-toast";
import { MessageSquare, Send, Users, Wifi, WifiOff } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";

const USER_COLORS = [
  "text-cyan-400", "text-violet-400", "text-emerald-400", "text-amber-400",
  "text-rose-400", "text-sky-400", "text-fuchsia-400", "text-lime-400",
  "text-orange-400", "text-pink-400",
];

function getUserColor(username: string) {
  let hash = 0;
  for (let i = 0; i < username.length; i++) hash = username.charCodeAt(i) + ((hash << 5) - hash);
  return USER_COLORS[Math.abs(hash) % USER_COLORS.length];
}

function formatTime(iso: string) {
  return new Date(iso).toLocaleTimeString("id-ID", { hour: "2-digit", minute: "2-digit" });
}

export default function ChatPage() {
  const { user } = useAuth();
  const { toast } = useToast();
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState("");
  const [online, setOnline] = useState(0);
  const [connected, setConnected] = useState(false);
  const bottomRef = useRef<HTMLDivElement>(null);
  const esRef = useRef<EventSource | null>(null);
  const sendMutation = useSendChatMessage();

  const { data: history, isLoading } = useGetChatMessages({ limit: 50 });

  useEffect(() => {
    if (history) setMessages(history);
  }, [history]);

  const scrollToBottom = useCallback(() => {
    setTimeout(() => bottomRef.current?.scrollIntoView({ behavior: "smooth" }), 50);
  }, []);

  useEffect(() => { scrollToBottom(); }, [messages, scrollToBottom]);

  useEffect(() => {
    const token = localStorage.getItem("mdw_token");
    if (!token) return;

    const base = import.meta.env.BASE_URL.replace(/\/$/, "");
    const url = `${base}/api/chat/stream?token=${encodeURIComponent(token)}`;
    const es = new EventSource(url);
    esRef.current = es;

    es.addEventListener("connected", () => setConnected(true));

    es.addEventListener("message", (e) => {
      try {
        const data = JSON.parse(e.data);
        if (data.type === "online_count") {
          setOnline(data.count);
        } else if (data.type === "chat") {
          const msg: ChatMessage = {
            id: data.id, userId: data.userId, username: data.username,
            message: data.message, createdAt: data.createdAt,
          };
          setMessages((prev) => {
            if (prev.find((m) => m.id === msg.id)) return prev;
            return [...prev, msg];
          });
        }
      } catch { }
    });

    es.onerror = () => setConnected(false);

    return () => { es.close(); esRef.current = null; setConnected(false); };
  }, []);

  const handleSend = () => {
    const text = input.trim();
    if (!text || sendMutation.isPending) return;
    setInput("");
    sendMutation.mutate(
      { data: { message: text } },
      { onError: () => { toast({ title: "Gagal mengirim pesan", variant: "destructive" }); setInput(text); } }
    );
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); handleSend(); }
  };

  return (
    <div className="flex flex-col h-[calc(100vh-140px)] max-h-[800px]">
      <div className="flex items-center justify-between mb-4 flex-shrink-0">
        <div className="flex items-center gap-3">
          <MessageSquare className="text-primary" size={24} />
          <div>
            <h1 className="text-2xl font-black font-mono text-foreground tracking-tight">GRUP CHAT</h1>
            <p className="text-muted-foreground font-mono text-xs">Chat real-time dengan semua user</p>
          </div>
        </div>
        <div className="flex items-center gap-4">
          <div className="flex items-center gap-1.5 font-mono text-xs text-muted-foreground">
            <Users size={13} /><span>{online} online</span>
          </div>
          <div className={`flex items-center gap-1.5 font-mono text-xs ${connected ? "text-emerald-400" : "text-red-400"}`}>
            {connected ? <Wifi size={13} /> : <WifiOff size={13} />}
            <span>{connected ? "TERHUBUNG" : "TERPUTUS"}</span>
          </div>
        </div>
      </div>

      <div className="flex-1 glass-panel rounded-xl border border-primary/20 overflow-y-auto p-4 space-y-3 min-h-0">
        {isLoading && (
          <div className="flex items-center justify-center h-full text-muted-foreground font-mono text-sm animate-pulse">
            Memuat pesan...
          </div>
        )}
        {!isLoading && messages.length === 0 && (
          <div className="flex flex-col items-center justify-center h-full text-muted-foreground font-mono text-sm gap-2">
            <MessageSquare size={32} className="opacity-20" />
            <p>Belum ada pesan. Mulai obrolan!</p>
          </div>
        )}
        {messages.map((msg) => {
          const isMe = msg.userId === user?.id;
          const color = getUserColor(msg.username);
          return (
            <div key={msg.id} className={`flex gap-2 ${isMe ? "flex-row-reverse" : "flex-row"}`}>
              <div className={`flex-shrink-0 w-7 h-7 rounded-full border flex items-center justify-center text-xs font-bold font-mono ${
                isMe ? "bg-primary/20 border-primary/50 text-primary" : "bg-white/5 border-white/10 " + color
              }`}>
                {msg.username.charAt(0).toUpperCase()}
              </div>
              <div className={`max-w-[70%] ${isMe ? "items-end" : "items-start"} flex flex-col gap-0.5`}>
                <div className={`flex items-center gap-2 ${isMe ? "flex-row-reverse" : "flex-row"}`}>
                  <span className={`font-mono text-xs font-bold ${isMe ? "text-primary" : color}`}>
                    {isMe ? "Kamu" : msg.username}
                  </span>
                  <span className="text-muted-foreground font-mono text-[10px]">{formatTime(msg.createdAt)}</span>
                </div>
                <div className={`px-3 py-2 rounded-xl text-sm font-mono break-words ${
                  isMe
                    ? "bg-primary/20 border border-primary/30 text-foreground rounded-tr-sm"
                    : "bg-white/5 border border-white/10 text-foreground rounded-tl-sm"
                }`}>
                  {msg.message}
                </div>
              </div>
            </div>
          );
        })}
        <div ref={bottomRef} />
      </div>

      <div className="flex gap-2 mt-3 flex-shrink-0">
        <Input
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder={connected ? "Ketik pesan..." : "Menghubungkan..."}
          disabled={!connected || sendMutation.isPending}
          maxLength={500}
          className="font-mono bg-background/50 border-primary/30 focus:border-primary focus:ring-primary/20 flex-1"
        />
        <Button
          onClick={handleSend}
          disabled={!input.trim() || !connected || sendMutation.isPending}
          className="font-mono bg-primary text-primary-foreground hover:bg-primary/90 neon-border px-4"
        >
          {sendMutation.isPending ? (
            <div className="w-4 h-4 border-2 border-primary-foreground/40 border-t-primary-foreground rounded-full animate-spin" />
          ) : (
            <Send size={16} />
          )}
        </Button>
      </div>
      <p className="text-muted-foreground font-mono text-[10px] mt-1 text-right">
        {input.length}/500 · Enter untuk kirim
      </p>
    </div>
  );
}
```

Ini semua kodenya — tidak ada C++ di sini, murni TypeScript/React. Ada yang ingin diubah atau ditambahkan?

Bisa, tapi hasilnya akan jadi program **C++ berbasis terminal** (bukan web browser) yang terhubung ke server yang sama. Ini kode C++ equivalennya:

```cpp
#include <iostream>
#include <string>
#include <thread>
#include <vector>
#include <functional>
#include <sstream>
#include <curl/curl.h>
#include <nlohmann/json.hpp>

using json = nlohmann::json;

// ─── Config ───────────────────────────────────────────────
const std::string BASE_URL    = "http://localhost:8080/api";
const std::string MDW_TOKEN   = "ISI_TOKEN_ANDA_DISINI";
// ──────────────────────────────────────────────────────────

struct ChatMessage {
    int         id;
    int         userId;
    std::string username;
    std::string message;
    std::string createdAt;
};

int currentUserId = -1;
int onlineCount   = 0;
bool connected    = false;
std::vector<ChatMessage> messages;

// ─── HTTP write callback ───────────────────────────────────
static size_t WriteCallback(char* ptr, size_t size, size_t nmemb, std::string* data) {
    data->append(ptr, size * nmemb);
    return size * nmemb;
}

// ─── Warna username ───────────────────────────────────────
std::string getUserColor(const std::string& username) {
    const std::vector<std::string> colors = {
        "\033[36m",  // cyan
        "\033[35m",  // violet
        "\033[32m",  // green
        "\033[33m",  // yellow
        "\033[31m",  // red
        "\033[34m",  // blue
        "\033[95m",  // fuchsia
        "\033[92m",  // lime
        "\033[93m",  // orange
        "\033[91m",  // pink
    };
    int hash = 0;
    for (char c : username) hash = c + ((hash << 5) - hash);
    return colors[std::abs(hash) % colors.size()];
}

// ─── Format waktu ─────────────────────────────────────────
std::string formatTime(const std::string& iso) {
    // Ambil jam:menit dari ISO string (format: 2026-06-03T12:34:56.000Z)
    if (iso.size() >= 16) return iso.substr(11, 5);
    return iso;
}

// ─── Tampilkan pesan ──────────────────────────────────────
void printMessage(const ChatMessage& msg) {
    bool isMe = (msg.userId == currentUserId);
    std::string color = isMe ? "\033[96m" : getUserColor(msg.username);
    std::string reset = "\033[0m";
    std::string name  = isMe ? "Kamu" : msg.username;

    if (isMe) {
        std::cout << "\033[2K\r"
                  << std::string(40, ' ')
                  << color << "[" << name << "]" << reset
                  << " \033[90m" << formatTime(msg.createdAt) << reset << "\n"
                  << std::string(40, ' ')
                  << msg.message << "\n";
    } else {
        std::cout << "\033[2K\r"
                  << color << "[" << name << "]" << reset
                  << " \033[90m" << formatTime(msg.createdAt) << reset << "\n"
                  << "  " << msg.message << "\n";
    }
}

// ─── SSE Stream: terima pesan real-time ───────────────────
static size_t SSECallback(char* ptr, size_t size, size_t nmemb, void* userdata) {
    size_t total = size * nmemb;
    std::string chunk(ptr, total);
    std::istringstream stream(chunk);
    std::string line;

    while (std::getline(stream, line)) {
        if (line.rfind("data:", 0) == 0) {
            std::string dataStr = line.substr(5);
            if (dataStr.empty()) continue;
            try {
                json data = json::parse(dataStr);
                std::string type = data.value("type", "");

                if (type == "online_count") {
                    onlineCount = data.value("count", 0);
                    std::cout << "\r\033[90m[" << onlineCount << " online]\033[0m\n";
                } else if (type == "chat") {
                    ChatMessage msg;
                    msg.id        = data.value("id", 0);
                    msg.userId    = data.value("userId", 0);
                    msg.username  = data.value("username", "");
                    msg.message   = data.value("message", "");
                    msg.createdAt = data.value("createdAt", "");

                    bool exists = false;
                    for (auto& m : messages)
                        if (m.id == msg.id) { exists = true; break; }

                    if (!exists) {
                        messages.push_back(msg);
                        printMessage(msg);
                    }
                } else if (type == "connected") {
                    connected = true;
                    std::cout << "\033[92m[TERHUBUNG]\033[0m\n";
                }
            } catch (...) {}
        }
    }
    return total;
}

// ─── Kirim pesan ──────────────────────────────────────────
void sendMessage(const std::string& text) {
    CURL* curl = curl_easy_init();
    if (!curl) return;

    std::string url = BASE_URL + "/chat/messages";
    json body = { {"message", text} };
    std::string bodyStr = body.dump();
    std::string response;

    struct curl_slist* headers = nullptr;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    std::string authHeader = "Authorization: Bearer " + MDW_TOKEN;
    headers = curl_slist_append(headers, authHeader.c_str());

    curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, bodyStr.c_str());
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteCallback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);
    curl_easy_perform(curl);

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
}

// ─── SSE listener di thread terpisah ──────────────────────
void startSSEListener() {
    std::thread([]() {
        CURL* curl = curl_easy_init();
        if (!curl) return;

        std::string url = BASE_URL + "/chat/stream?token=" + MDW_TOKEN;
        struct curl_slist* headers = nullptr;
        headers = curl_slist_append(headers, "Accept: text/event-stream");

        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, SSECallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, nullptr);
        curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
        curl_easy_perform(curl);

        connected = false;
        std::cout << "\033[91m[TERPUTUS]\033[0m\n";
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
    }).detach();
}

// ─── Main ──────────────────────────────────────────────────
int main() {
    curl_global_init(CURL_GLOBAL_ALL);

    std::cout << "\033[96m"
              << " ___  ___  ________  ___       __       \n"
              << "|\\  \\|\\  \\|\\   ___ \\|\\  \\     |\\  \\     \n"
              << "\\ \\  \\\\\\  \\ \\  \\_|\\ \\ \\  \\    \\ \\  \\    \n"
              << " \\ \\   __  \\ \\  \\ \\\\ \\ \\  \\  __\\ \\  \\   \n"
              << "  \\ \\  \\ \\  \\ \\  \\_\\\\ \\ \\  \\|\\__\\_\\  \\  \n"
              << "   \\ \\__\\ \\__\\ \\_______\\ \\____________\\  \n"
              << "    \\|__|\\|__|\\|_______|\\|____________|  \n"
              << "\033[0m\n"
              << "\033[90mGRUP CHAT — MDW Panel v1.0\033[0m\n"
              << "Ketik pesan lalu Enter. Ctrl+C untuk keluar.\n"
              << std::string(50, '-') << "\n\n";

    startSSEListener();

    std::string input;
    while (true) {
        std::cout << "\033[96m[Kamu]>\033[0m ";
        if (!std::getline(std::cin, input)) break;
        if (input.empty()) continue;
        if (input.length() > 500) {
            std::cout << "\033[91mPesan terlalu panjang (max 500 karakter)\033[0m\n";
            continue;
        }
        sendMessage(input);
    }

    curl_global_cleanup();
    return 0;
}
```

**Cara compile:**
```bash
g++ -std=c++17 chat.cpp -o chat -lcurl
./chat
```

**Dependencies yang dibutuhkan:**
- `libcurl` — untuk HTTP & SSE
- `nlohmann/json` — untuk parse JSON

Isi `MDW_TOKEN` dengan token login Anda, dan `BASE_URL` sesuaikan dengan URL server. Program ini akan terhubung ke server MDW Panel yang sama dan bisa kirim/terima pesan dari terminal.

