#include <string>
#include <vector>
#include <algorithm>
#include <pthread.h>
#include <curl/curl.h>
#include <nlohmann/json.hpp>
#include <imgui.h>

using json = nlohmann::json;

// ─── CONFIG ─────────────────────────────────────────────────
static const std::string BASE_URL  = "https://mdwpanel.replit.app/api";
static const std::string MDW_TOKEN = "ISI_TOKEN_ANDA_DISINI";
// ────────────────────────────────────────────────────────────

// ─── STRUCT PESAN (setara ChatMessage di chat.tsx) ───────────
struct ChatMessage {
    int         id       = 0;
    int         userId   = 0;
    std::string username;
    std::string message;
    std::string time;     // sudah diformat HH:MM
    std::string createdAt;
};

// ─── VARIABEL GLOBAL ─────────────────────────────────────────
std::vector<ChatMessage> g_chatMessages;
pthread_mutex_t          g_chatMutex    = PTHREAD_MUTEX_INITIALIZER;
bool                     g_connected    = false;
bool                     g_isLoading    = true;
bool                     g_scrollToBottom = false;
int                      g_onlineUsers  = 0;
int                      g_myUserId     = -1;   // diisi setelah login
std::string              g_chatInput    = "";

// ─── FORMAT WAKTU (setara formatTime di chat.tsx) ────────────
static std::string formatTime(const std::string& iso) {
    // ISO: "2026-06-03T12:34:56.000Z" → "12:34"
    if (iso.size() >= 16) return iso.substr(11, 5);
    return iso;
}

// ─── WARNA USERNAME (setara getUserColor di chat.tsx) ────────
static ImVec4 getUserColor(const std::string& username) {
    static const ImVec4 colors[] = {
        {0.25f, 0.88f, 0.88f, 1.f},  // cyan
        {0.60f, 0.40f, 0.96f, 1.f},  // violet
        {0.24f, 0.82f, 0.53f, 1.f},  // emerald
        {0.96f, 0.76f, 0.26f, 1.f},  // amber
        {0.96f, 0.33f, 0.45f, 1.f},  // rose
        {0.23f, 0.73f, 0.96f, 1.f},  // sky
        {0.90f, 0.30f, 0.96f, 1.f},  // fuchsia
        {0.60f, 0.98f, 0.20f, 1.f},  // lime
        {0.98f, 0.55f, 0.20f, 1.f},  // orange
        {0.98f, 0.45f, 0.76f, 1.f},  // pink
    };
    int hash = 0;
    for (char c : username) hash = c + ((hash << 5) - hash);
    int idx = std::abs(hash) % (sizeof(colors) / sizeof(colors[0]));
    return colors[idx];
}

// ─── HTTP WRITE CALLBACK ─────────────────────────────────────
static size_t WriteCallback(char* ptr, size_t size, size_t nmemb, std::string* out) {
    out->append(ptr, size * nmemb);
    return size * nmemb;
}

// ─── FETCH HISTORY (setara useGetChatMessages di chat.tsx) ───
static void FetchChatHistory() {
    CURL* curl = curl_easy_init();
    if (!curl) return;

    std::string url = BASE_URL + "/chat/messages?limit=50";
    std::string response;
    std::string authHeader = "Authorization: Bearer " + MDW_TOKEN;

    struct curl_slist* headers = nullptr;
    headers = curl_slist_append(headers, authHeader.c_str());
    headers = curl_slist_append(headers, "Content-Type: application/json");

    curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
