// ─── SSE CALLBACK (parse event stream, setara EventSource di chat.tsx) ──
static size_t SSECallback(char* ptr, size_t size, size_t nmemb, void*) {
    size_t total = size * nmemb;
    std::string chunk(ptr, total);

    std::istringstream stream(chunk);
    std::string line;
    while (std::getline(stream, line)) {
        if (line.rfind("data:", 0) != 0) continue;
        std::string dataStr = line.substr(5);
        if (dataStr.empty()) continue;

        try {
            auto data = json::parse(dataStr);
            std::string type = data.value("type", "");

            if (type == "connected") {
                g_connected = true;

            } else if (type == "online_count") {
                g_onlineUsers = data.value("count", 0);

            } else if (type == "chat") {
                ChatMessage msg;
                msg.id        = data.value("id", 0);
                msg.userId    = data.value("userId", 0);
                msg.username  = data.value("username", "");
                msg.message   = data.value("message", "");
                msg.createdAt = data.value("createdAt", "");
                msg.time      = formatTime(msg.createdAt);

                pthread_mutex_lock(&g_chatMutex);
                // Cek duplikat (setara prev.find di chat.tsx)
                bool exists = false;
                for (auto& m : g_chatMessages)
                    if (m.id == msg.id) { exists = true; break; }

                if (!exists) {
                    g_chatMessages.push_back(msg);
                    g_scrollToBottom = true;
                }
                pthread_mutex_unlock(&g_chatMutex);
            }
        } catch (...) {}
    }
    return total;
}

