// ─── HTTP WRITE CALLBACK ─────────────────────────────────────
static size_t WriteCallback(char* ptr, size_t size, size_t nmemb, std::string* out) {
    out->append(ptr, size * nmemb);
    return size * nmemb;
}

// ─── SSE BUFFER (untuk parse multi-line) ─────────────────────
struct SSEParser {
    std::string event_name;
    std::string data_buf;
    std::string leftover;  // sisa baris yang belum lengkap
};

static SSEParser g_sseParser;

static void processSSEEvent(const std::string& event_name, const std::string& data_str) {
    if (data_str.empty()) return;
    try {
        auto data = json::parse(data_str);

        // ── event: connected → set g_connected = true ────────
        if (event_name == "connected") {
            g_connected   = true;
            g_onlineUsers = data.value("online", 0);
        }
        // ── event: message → cek type di dalam data ──────────
        else if (event_name == "message") {
            std::string type = data.value("type", "");

            if (type == "online_count") {
                g_onlineUsers = data.value("count", 0);
            }
            else if (type == "chat") {
                ChatMessage msg;
                msg.id        = data.value("id", 0);
                msg.userId    = data.value("userId", 0);
                msg.username  = data.value("username", "");
                msg.message   = data.value("message", "");
                msg.createdAt = data.value("createdAt", "");
                msg.time      = formatTime(msg.createdAt);

                pthread_mutex_lock(&g_chatMutex);
                bool exists = false;
                for (auto& m : g_chatMessages)
                    if (m.id == msg.id) { exists = true; break; }
                if (!exists) {
                    g_chatMessages.push_back(msg);
                    g_scrollToBottom = true;
                }
                pthread_mutex_unlock(&g_chatMutex);
            }
        }
    } catch (...) {}
}

// ─── SSE CURL CALLBACK (FIXED: baca event: dan data:) ────────
static size_t SSECallback(char* ptr, size_t size, size_t nmemb, void* userdata) {
    SSEParser* parser = reinterpret_cast<SSEParser*>(userdata);
    std::string chunk = parser->leftover + std::string(ptr, size * nmemb);
    parser->leftover.clear();

    std::istringstream stream(chunk);
    std::string line;

    while (std::getline(stream, line)) {
        // Cek apakah baris ini lengkap (stream mungkin terpotong di tengah)
        if (stream.eof() && !chunk.empty() && chunk.back() != '\n') {
            parser->leftover = line;
            break;
        }

        // Hapus '\r' jika ada (Windows line endings)
        if (!line.empty() && line.back() == '\r')
            line.pop_back();

        if (line.rfind("event:", 0) == 0) {
            // Baca nama event
            parser->event_name = line.substr(6);
            while (!parser->event_name.empty() && parser->event_name.front() == ' ')
                parser->event_name.erase(parser->event_name.begin());

        } else if (line.rfind("data:", 0) == 0) {
            // Baca data
            parser->data_buf = line.substr(5);
            while (!parser->data_buf.empty() && parser->data_buf.front() == ' ')
                parser->data_buf.erase(parser->data_buf.begin());

        } else if (line.empty()) {
            // Baris kosong = event selesai, proses sekarang
            if (!parser->data_buf.empty()) {
                processSSEEvent(parser->event_name, parser->data_buf);
            }
            parser->event_name.clear();
            parser->data_buf.clear();
        }
    }

    return size * nmemb;
}

// ─── FETCH HISTORY ───────────────────────────────────────────
static void FetchChatHistory() {
    CURL* curl = curl_easy_init();
    if (!curl) return;

    std::string url     = BASE_URL + "/chat/messages?limit=50";
    std::string response;
    std::string authHdr = "Authorization: Bearer " + MDW_TOKEN;

    struct curl_slist* headers = nullptr;
    headers = curl_slist_append(headers, authHdr.c_str());

    curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteCallback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_perform(curl);
    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);

    try {
        auto arr = json::parse(response);
        pthread_mutex_lock(&g_chatMutex);
        g_chatMessages.clear();
        for (auto& item : arr) {
            ChatMessage msg;
            msg.id        = item.value("id", 0);
            msg.userId    = item.value("userId", 0);
            msg.username  = item.value("username", "");
            msg.message   = item.value("message", "");
            msg.createdAt = item.value("createdAt", "");
            msg.time      = formatTime(msg.createdAt);
            g_chatMessages.push_back(msg);
        }
        g_isLoading      = false;
        g_scrollToBottom = true;
        pthread_mutex_unlock(&g_chatMutex);
    } catch (...) {}
}

// ─── THREAD: SSE POLLING (FIXED) ─────────────────────────────
void* ChatPollingThread(void*) {
    FetchChatHistory();

    while (true) {
        CURL* curl = curl_easy_init();
        if (!curl) { sleep(3); continue; }

        std::string url = BASE_URL + "/chat/stream?token=" + MDW_TOKEN;

        struct curl_slist* headers = nullptr;
        headers = curl_slist_append(headers, "Accept: text/event-stream");
        headers = curl_slist_append(headers, "Cache-Control: no-cache");

        // Reset parser & status sebelum connect
        g_sseParser = SSEParser{};
        g_connected = false;

        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, SSECallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &g_sseParser); // ← kirim parser
        curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
        curl_easy_perform(curl);  // blokir sampai putus

        g_connected = false;
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        sleep(3);  // reconnect otomatis
    }
    return nullptr;
}

// ─── THREAD: KIRIM PESAN ─────────────────────────────────────
void* SendMessagesThread(void*) {
    pthread_mutex_lock(&g_chatMutex);
    std::string textToSend = g_chatInput;
    g_chatInput = "";
    pthread_mutex_unlock(&g_chatMutex);

    if (textToSend.empty() || textToSend.size() > 500) return nullptr;

    CURL* curl = curl_easy_init();
    if (!curl) return nullptr;

    std::string url     = BASE_URL + "/chat/messages";
    json body           = { {"message", textToSend} };
    std::string bodyStr = body.dump();
    std::string response;
    std::string authHdr = "Authorization: Bearer " + MDW_TOKEN;

    struct curl_slist* headers = nullptr;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    headers = curl_slist_append(headers, authHdr.c_str());

    curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, bodyStr.c_str());
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteCallback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_perform(curl);
    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return nullptr;
}

