// Normalisasi teks: hapus spasi & karakter khusus, lowercase
function normalize(text: string): string {
  return text
    .toLowerCase()
    .replace(/[*@#$!0-9]/g, (c) => ({
      "*": "", "@": "a", "#": "h", "$": "s", "!": "i",
      "0": "o", "1": "i", "3": "e", "4": "a", "5": "s",
    }[c] ?? ""))
    .replace(/\s+/g, " ")
    .trim();
}

export function containsProfanity(message: string): boolean {
