  const words = normalized.split(/\s+/);
  for (const bad of PROFANITY_LIST) {
    const normalBad = normalize(bad);
    if (normalized.includes(normalBad)) return true;
    if (words.some(w => w === normalBad)) return true;
  }
  return false;
}

