  for (const res of clients.values()) {
    try { res.write(payload); } catch { /* client disconnected */ }
  }
}

// ─── Cek apakah chat sedang di-mute ──────────────────────────
async function isChatMuted(): Promise<boolean> {
  const rows = await db.select().from(settingsTable)
    .where(eq(settingsTable.key, "chat_muted")).limit(1);
  return rows[0]?.value === "true";
}

// ─── SSE Stream ───────────────────────────────────────────────
router.get("/chat/stream", async (req, res) => {
  const token = req.query.token as string;
  if (!token) { res.status(401).json({ error: "Unauthorized" }); return; }

  try {
    const payload = jwt.verify(token, JWT_SECRET) as { userId: number };
    const users = await db.select().from(usersTable)
      .where(eq(usersTable.id, payload.userId)).limit(1);
    if (!users.length || users[0].banned) {
      res.status(401).json({ error: "Unauthorized" }); return;
    }
  } catch {
    res.status(401).json({ error: "Invalid token" }); return;
  }

  res.setHeader("Content-Type", "text/event-stream");
  res.setHeader("Cache-Control", "no-cache");
  res.setHeader("Connection", "keep-alive");
  res.setHeader("X-Accel-Buffering", "no");
  res.flushHeaders();

  const clientId = String(++clientIdCounter);
  clients.set(clientId, res);

  const muted = await isChatMuted();
  res.write(`event: connected\ndata: ${JSON.stringify({ ok: true, online: clients.size, muted })}\n\n`);
  broadcast({ type: "online_count", count: clients.size });

  req.on("close", () => {
    clients.delete(clientId);
    broadcast({ type: "online_count", count: clients.size });
  });
});

// ─── GET Messages ─────────────────────────────────────────────
router.get("/chat/messages", requireAuth, async (req: AuthRequest, res) => {
  const limit = Math.min(parseInt(String(req.query.limit ?? "50")), 100);
  const messages = await db.select()
    .from(chatMessagesTable)
    .orderBy(desc(chatMessagesTable.createdAt))
    .limit(limit);
  res.json(messages.reverse().map((m) => ({
    ...m,
    createdAt: m.createdAt.toISOString(),
  })));
});

// ─── POST Send Message ────────────────────────────────────────
router.post("/chat/messages", requireAuth, async (req: AuthRequest, res) => {
  const parsed = SendChatMessageBody.safeParse(req.body);
  if (!parsed.success) { res.status(400).json({ error: "Pesan tidak valid" }); return; }

  const user = req.user!;

  // Admin tidak kena batasan
  if (user.role !== "admin") {
    // Cek chat muted
    const muted = await isChatMuted();
    if (muted) {
      res.status(403).json({ error: "Chat sedang dinonaktifkan oleh admin" });
      return;
    }

    // Cek akun frozen
    const freshUser = await db.select().from(usersTable).where(eq(usersTable.id, user.id)).limit(1);
    const u = freshUser[0];
    if (u?.frozenUntil && new Date(u.frozenUntil) > new Date()) {
      const until = new Date(u.frozenUntil).toLocaleString("id-ID");
      res.status(403).json({ error: `Akun Anda dibekukan hingga ${until} karena kata kasar` });
      return;
    }

    // Deteksi kata kotor
    if (containsProfanity(parsed.data.message)) {
      const newCount = (u?.profanityCount ?? 0) + 1;

      if (newCount >= 3) {
        // Pelanggaran ke-3+: cek apakah sudah pernah dibekukan sebelumnya
        const alreadyFrozenBefore = u?.frozenUntil !== null && u?.frozenUntil !== undefined;

        if (alreadyFrozenBefore) {
          // Pernah dibekukan sebelumnya → blokir permanen
          await db.update(usersTable).set({
            banned: true,
            profanityCount: newCount,
          }).where(eq(usersTable.id, user.id));
          broadcast({ type: "user_banned", userId: user.id, username: user.username });
          res.status(403).json({ error: "Akun Anda diblokir permanen karena berulang kali menggunakan kata kasar" });
        } else {
          // Pertama kali 3x → bekukan 1 hari
          const frozenUntil = new Date(Date.now() + 24 * 60 * 60 * 1000);
          await db.update(usersTable).set({
            profanityCount: newCount,
            frozenUntil,
          }).where(eq(usersTable.id, user.id));
          const until = frozenUntil.toLocaleString("id-ID");
          res.status(403).json({ error: `Akun Anda dibekukan 1 hari hingga ${until} karena kata kasar (peringatan ke-${newCount})` });
        }
        return;
      } else {
        // Peringatan 1-2
        await db.update(usersTable).set({ profanityCount: newCount }).where(eq(usersTable.id, user.id));
        res.status(400).json({ error: `Pesan mengandung kata kasar. Peringatan ${newCount}/3 — akun akan dibekukan jika mencapai 3` });
        return;
      }
    }
  }

  const [msg] = await db.insert(chatMessagesTable).values({
    userId: user.id,
    username: user.username,
    message: parsed.data.message,
  }).returning();

  const out = {
    id: msg.id,
    userId: msg.userId,
    username: msg.username,
    message: msg.message,
    createdAt: msg.createdAt.toISOString(),
  };

  broadcast({ type: "chat", ...out });
  res.status(201).json(out);
});

// ─── DELETE Message (admin only) ─────────────────────────────
router.delete("/chat/messages/:id", requireAdmin, async (req: AuthRequest, res) => {
  const id = parseInt(req.params.id);
  if (isNaN(id)) { res.status(400).json({ error: "Invalid id" }); return; }

  await db.delete(chatMessagesTable).where(eq(chatMessagesTable.id, id));
  broadcast({ type: "message_deleted", id });
  res.json({ success: true });
});

// ─── GET Chat Mute Status ─────────────────────────────────────
router.get("/chat/mute", requireAuth, async (_req, res) => {
  const muted = await isChatMuted();
  res.json({ muted });
});

// ─── POST Toggle Chat Mute (admin only) ──────────────────────
router.post("/chat/mute", requireAdmin, async (_req: AuthRequest, res) => {
  const current = await isChatMuted();
  const newVal = !current;

  const existing = await db.select().from(settingsTable)
    .where(eq(settingsTable.key, "chat_muted")).limit(1);

  if (existing.length) {
    await db.update(settingsTable).set({ value: String(newVal), updatedAt: new Date() })
      .where(eq(settingsTable.key, "chat_muted"));
  } else {
    await db.insert(settingsTable).values({ key: "chat_muted", value: String(newVal) });
  }

  broadcast({ type: "chat_muted", muted: newVal });
  res.json({ muted: newVal });
});

export default router;

import { useEffect, useRef, useState, useCallback } from "react";
import { useGetChatMessages, useSendChatMessage } from "@workspace/api-client-react";
import type { ChatMessage } from "@workspace/api-client-react";
import { useAuth } from "@/lib/auth";
import { useToast } from "@/hooks/use-toast";
import { MessageSquare, Send, Users, Wifi, WifiOff, Trash2, ShieldOff, Shield } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";

const USER_COLORS = [
  "text-cyan-400","text-violet-400","text-emerald-400","text-amber-400",
  "text-rose-400","text-sky-400","text-fuchsia-400","text-lime-400",
  "text-orange-400","text-pink-400",
];

function getUserColor(username: string) {
  let hash = 0;
  for (let i = 0; i < username.length; i++) hash = username.charCodeAt(i) + ((hash << 5) - hash);
  return USER_COLORS[Math.abs(hash) % USER_COLORS.length];
}

function formatTime(iso: string) {
  return new Date(iso).toLocaleTimeString("id-ID", { hour: "2-digit", minute: "2-digit" });
}

const BASE = import.meta.env.BASE_URL.replace(/\/$/, "");

export default function ChatPage() {
  const { user } = useAuth();
  const { toast } = useToast();
  const isAdmin = user?.role === "admin";

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState("");
  const [online, setOnline] = useState(0);
  const [connected, setConnected] = useState(false);
  const [muted, setMuted] = useState(false);
  const [mutingLoading, setMutingLoading] = useState(false);
  const bottomRef = useRef<HTMLDivElement>(null);
  const esRef = useRef<EventSource | null>(null);
  const sendMutation = useSendChatMessage();

  const { data: history, isLoading } = useGetChatMessages({ limit: 50 });

  useEffect(() => {
    if (history) setMessages(history);
  }, [history]);

  const scrollToBottom = useCallback(() => {
    setTimeout(() => bottomRef.current?.scrollIntoView({ behavior: "smooth" }), 50);
  }, []);

  useEffect(() => { scrollToBottom(); }, [messages, scrollToBottom]);

  useEffect(() => {
    const token = localStorage.getItem("mdw_token");
    if (!token) return;

    const url = `${BASE}/api/chat/stream?token=${encodeURIComponent(token)}`;
    const es = new EventSource(url);
    esRef.current = es;

    es.addEventListener("connected", (e) => {
      setConnected(true);
      try {
        const d = JSON.parse(e.data);
        if (typeof d.muted === "boolean") setMuted(d.muted);
      } catch { /* ignore */ }
    });

    es.addEventListener("message", (e) => {
      try {
        const data = JSON.parse(e.data);
        if (data.type === "online_count") {
          setOnline(data.count);
        } else if (data.type === "chat") {
          const msg: ChatMessage = {
            id: data.id, userId: data.userId, username: data.username,
            message: data.message, createdAt: data.createdAt,
          };
          setMessages((prev) => {
            if (prev.find((m) => m.id === msg.id)) return prev;
            return [...prev, msg];
          });
        } else if (data.type === "message_deleted") {
          setMessages((prev) => prev.filter((m) => m.id !== data.id));
        } else if (data.type === "chat_muted") {
          setMuted(data.muted);
          toast({
            title: data.muted ? "⛔ Chat dinonaktifkan oleh admin" : "✅ Chat diaktifkan kembali",
          });
        }
      } catch { /* ignore */ }
    });

    es.onerror = () => setConnected(false);
    return () => { es.close(); esRef.current = null; setConnected(false); };
  }, []);

  const handleSend = () => {
    const text = input.trim();
    if (!text || sendMutation.isPending) return;
    setInput("");
    sendMutation.mutate(
      { data: { message: text } },
      {
        onError: (err: any) => {
          const msg = err?.response?.data?.error ?? "Gagal mengirim pesan";
          toast({ title: msg, variant: "destructive" });
          setInput(text);
        },
      }
    );
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); handleSend(); }
  };

  const handleDelete = async (id: number) => {
    try {
      const token = localStorage.getItem("mdw_token");
      await fetch(`${BASE}/api/chat/messages/${id}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });
    } catch {
      toast({ title: "Gagal menghapus pesan", variant: "destructive" });
    }
  };

  const handleToggleMute = async () => {
    setMutingLoading(true);
    try {
      const token = localStorage.getItem("mdw_token");
      const r = await fetch(`${BASE}/api/chat/mute`, {
        method: "POST",
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await r.json();
      setMuted(data.muted);
      toast({ title: data.muted ? "⛔ Chat dinonaktifkan" : "✅ Chat diaktifkan" });
    } catch {
      toast({ title: "Gagal mengubah status chat", variant: "destructive" });
    } finally {
      setMutingLoading(false);
    }
  };

  const canSend = connected && !sendMutation.isPending && (isAdmin || !muted);

  return (
    <div className="flex flex-col h-[calc(100vh-140px)] max-h-[800px]">
      {/* Header */}
      <div className="flex items-center justify-between mb-4 flex-shrink-0">
        <div className="flex items-center gap-3">
          <MessageSquare className="text-primary" size={24} />
          <div>
            <h1 className="text-2xl font-black font-mono text-foreground tracking-tight">GRUP CHAT</h1>
            <p className="text-muted-foreground font-mono text-xs">Chat real-time dengan semua user</p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          {/* Mute toggle — admin only */}
          {isAdmin && (
            <Button
              size="sm"
              variant="outline"
              onClick={handleToggleMute}
              disabled={mutingLoading}
              className={`font-mono text-xs flex items-center gap-1.5 ${
                muted
                  ? "border-red-500/40 text-red-400 hover:bg-red-500/10"
                  : "border-primary/30 text-muted-foreground hover:text-primary hover:border-primary/60"
              }`}
            >
              {muted ? <ShieldOff size={13} /> : <Shield size={13} />}
              {muted ? "AKTIFKAN CHAT" : "NONAKTIFKAN CHAT"}
            </Button>
          )}

          <div className="flex items-center gap-1.5 font-mono text-xs text-muted-foreground">
            <Users size={13} /><span>{online} online</span>
          </div>
          <div className={`flex items-center gap-1.5 font-mono text-xs ${connected ? "text-emerald-400" : "text-red-400"}`}>
            {connected ? <Wifi size={13} /> : <WifiOff size={13} />}
            <span>{connected ? "TERHUBUNG" : "TERPUTUS"}</span>
          </div>
        </div>
      </div>

      {/* Mute banner */}
      {muted && (
        <div className={`mb-3 px-4 py-2 rounded-lg border font-mono text-xs flex-shrink-0 ${
          isAdmin
            ? "bg-amber-500/10 border-amber-500/30 text-amber-400"
            : "bg-red-500/10 border-red-500/30 text-red-400"
        }`}>
          {isAdmin
            ? "⛔ Chat sedang dinonaktifkan. Hanya admin yang bisa mengirim pesan."
            : "⛔ Chat dinonaktifkan oleh admin. Anda tidak bisa mengirim pesan saat ini."}
        </div>
      )}

      {/* Message area */}
      <div className="flex-1 glass-panel rounded-xl border border-primary/20 overflow-y-auto p-4 space-y-3 min-h-0">
        {isLoading && (
          <div className="flex items-center justify-center h-full text-muted-foreground font-mono text-sm animate-pulse">
            Memuat pesan...
          </div>
        )}
        {!isLoading && messages.length === 0 && (
          <div className="flex flex-col items-center justify-center h-full text-muted-foreground font-mono text-sm gap-2">
            <MessageSquare size={32} className="opacity-20" />
            <p>Belum ada pesan. Mulai obrolan!</p>
          </div>
        )}
        {messages.map((msg) => {
          const isMe = msg.userId === user?.id;
          const color = getUserColor(msg.username);
          return (
            <div key={msg.id} className={`flex gap-2 group ${isMe ? "flex-row-reverse" : "flex-row"}`}>
              <div className={`flex-shrink-0 w-7 h-7 rounded-full border flex items-center justify-center text-xs font-bold font-mono ${
                isMe ? "bg-primary/20 border-primary/50 text-primary" : "bg-white/5 border-white/10 " + color
              }`}>
                {msg.username.charAt(0).toUpperCase()}
              </div>
              <div className={`max-w-[70%] ${isMe ? "items-end" : "items-start"} flex flex-col gap-0.5`}>
                <div className={`flex items-center gap-2 ${isMe ? "flex-row-reverse" : "flex-row"}`}>
                  <span className={`font-mono text-xs font-bold ${isMe ? "text-primary" : color}`}>
                    {isMe ? "Kamu" : msg.username}
                  </span>
                  <span className="text-muted-foreground font-mono text-[10px]">{formatTime(msg.createdAt)}</span>
                  {/* Delete button — admin only */}
                  {isAdmin && (
                    <button
                      onClick={() => handleDelete(msg.id)}
                      className="opacity-0 group-hover:opacity-100 transition-opacity p-0.5 text-red-400/60 hover:text-red-400 rounded"
                      title="Hapus pesan"
                    >
                      <Trash2 size={11} />
                    </button>
                  )}
                </div>
                <div className={`px-3 py-2 rounded-xl text-sm font-mono break-words ${
                  isMe
                    ? "bg-primary/20 border border-primary/30 text-foreground rounded-tr-sm"
                    : "bg-white/5 border border-white/10 text-foreground rounded-tl-sm"
                }`}>
                  {msg.message}
                </div>
              </div>
            </div>
          );
        })}
        <div ref={bottomRef} />
      </div>

      {/* Input area */}
      <div className="flex gap-2 mt-3 flex-shrink-0">
        <Input
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder={
            !connected ? "Menghubungkan..." :
            muted && !isAdmin ? "Chat dinonaktifkan oleh admin..." :
            "Ketik pesan..."
          }
          disabled={!canSend}
          maxLength={500}
          className="font-mono bg-background/50 border-primary/30 focus:border-primary focus:ring-primary/20 flex-1"
        />
        <Button
          onClick={handleSend}
          disabled={!input.trim() || !canSend}
          className="font-mono bg-primary text-primary-foreground hover:bg-primary/90 neon-border px-4"
        >
          {sendMutation.isPending ? (
            <div className="w-4 h-4 border-2 border-primary-foreground/40 border-t-primary-foreground rounded-full animate-spin" />
          ) : (
            <Send size={16} />
          )}
        </Button>
      </div>
      <p className="text-muted-foreground font-mono text-[10px] mt-1 text-right">
        {input.length}/500 · Enter untuk kirim
      </p>
    </div>
  );
}

